function LookinAtChoo2.init()
    local val = {}
    local trans = WorldTransform.new()
    local checkId = nil
    for _, point in ipairs(LookinAtChoo2.checkpoints) do
        trans:SetPosition(ToVector4(point.position))
        trans:SetOrientation(ToEulerAngles(point.rotation):ToQuat())
        checkId = exEntitySpawner.Spawn(LookinAtChoo2.checkpointEnts[_], trans)
        table.insert(val, _, checkId)
    end
    return val
end

